def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Determines if there are any two numbers in the given list that are closer to each other than the specified threshold.

    :param numbers: List of floating-point numbers to check.
    :param threshold: The threshold distance for considering two numbers as close.
    :return: True if there are two numbers closer than the threshold, False otherwise.
    """
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) < threshold:
                return True
    return False

