def count_passing_ways(n: int, m: int) -> int:
    MOD = 1000000007

    if m % 2 == 0:
        return pow(2, n, MOD)
    else:
        return (pow(2, n - 1, MOD) - 1) % MOD

def polynomial_to_string(n, coeffs):
    output = ''
    for i in range(n):
        if coeffs[i] != 0:
            term = f'{abs(coeffs[i]) if coeffs[i] != 1 else ""}{coeffs[i] if coeffs[i] > 0 else "-" if coeffs[i] < 0 else ""}x^'
            if i == n - 1:
                term += '1'
            else:
                term += '{}'.format('x' if i == n - 2 else 'x^{}'.format(n - i - 1))
            output = term + ' + ' + output if output else term
    return output.strip()

def largest_prime_factor(n: int) -> int:
    factor = 2
    while factor * factor <= n:
        if n % factor == 0:
            n //= factor
        else:
            factor += 1
    return n if n > 1 else factor

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n > last / 2:
        return 0
    if n == 1:
        return 1
    if n in memo:
        return memo[n]
    total = count_sequences(n, last, memo)
    memo[n] = total + count_sequences(n, last - n, memo)
    return total

def preorder_traversal(inorder: str, postorder: str) -> str:
    if len(inorder) != len(postorder):
        return ""

    def build_tree(postorder, inorder):
        if not inorder:
            return None

        root_val = postorder[-1]
        root = TreeNode(root_val)
        root_index = inorder.index(root_val)

        root.left = build_tree(postorder[:root_index], inorder[:root_index])
        root.right = build_tree(postorder[root_index:-1], inorder[root_index+1:])

        return root

    def preorder(node, result):
        if not node:
            return
        result.append(node.val)
        preorder(node.left, result)
        preorder(node.right, result)

    tree_root = build_tree(postorder, inorder)
    preorder_result = []
    preorder(tree_root, preorder_result)
    return ' '.join(map(str, preorder_result))

def generate_numbers(n, rules):
    if n == 0:
        return 0

    queue = [n]
    unique_numbers = {n}

    while queue:
        current_num = queue.pop(0)
        for rule in rules:
            # Apply each transformation rule
            new_num = current_num.replace(str(rule[0]), str(rule[1]))
            # Check if the new number is unique and hasn't been seen before
            if int(new_num) not in unique_numbers:
                unique_numbers.add(int(new_num))
                queue.append(int(new_num))

    # Return the total count of unique numbers
    return len(unique_numbers)

