def minimum_students_to_leave(heights):
    if len(heights) <= 2:
        return 0

    peaks = []
    valleys = []

    # Find peaks and valleys
    for i in range(1, len(heights) - 1):
        if heights[i] > heights[i - 1] and heights[i] > heights[i + 1]:
            peaks.append(i)
        if heights[i] < heights[i - 1] and heights[i] < heights[i + 1]:
            valleys.append(i)

    # Initialize the result with the number of peaks and valleys
    result = len(peaks) + len(valleys)

    # Check for extraneous boundaries
    if heights[0] <= heights[1]:
        result -= 1
    if heights[-1] <= heights[-2]:
        result -= 1

    # Return the minimum number of students to leave
    return result

def hanoi_double_iterative(n: int) -> int:
    total_moves = 0
    for i in range(n):
        total_moves += 2 * (2 ** i - 1)
    return total_moves
